messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Red vs Blue — three.js race</title>
  <style>
    body { margin: 0; overflow: hidden; background: #111; font-family: Arial, sans-serif; }
    #info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      background: rgba(0,0,0,0.6);
      padding: 8px 16px;
      border-radius: 8px;
      pointer-events: none;
      font-size: 14px;
      letter-spacing: 1px;
    }
    #status {
      position: absolute;
      top: 20px;
      right: 20px;
      color: white;
      background: rgba(0,0,0,0.6);
      padding: 8px 16px;
      border-radius: 8px;
      pointer-events: none;
      font-size: 16px;
      font-weight: bold;
    }
  </style>
</head>
<body>
  <div id="info">🏁 RED vs BLUE — straight track</div>
  <div id="status">BLUE leads</div>

  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>

  <script type="module">
    import * as THREE from './three.module.js';

    // --- Setup scene ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    // --- Camera ---
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 4.2, 12);
    camera.lookAt(0, 0.8, 2);

    // --- Renderer ---
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lights ---
    const ambient = new THREE.AmbientLight(0x404040, 0.6);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    scene.add(dirLight);

    const fillLight = new THREE.PointLight(0xffffff, 0.5);
    fillLight.position.set(-5, 3, 5);
    scene.add(fillLight);

    // --- Ground ---
    const groundGeo = new THREE.PlaneGeometry(30, 20);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a5a3a, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // --- Road ---
    const roadGeo = new THREE.PlaneGeometry(3.2, 30);
    const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.9 });
    const road = new THREE.Mesh(roadGeo, roadMat);
    road.rotation.x = -Math.PI / 2;
    road.position.y = 0.01;
    road.position.z = 0;
    road.receiveShadow = true;
    scene.add(road);

    // Road edge lines
    const lineMat = new THREE.MeshBasicMaterial({ color: 0xdddddd });
    const leftLine = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.02, 30), lineMat);
    leftLine.position.set(-1.6, 0.02, 0);
    leftLine.rotation.x = -Math.PI / 2;
    scene.add(leftLine);

    const rightLine = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.02, 30), lineMat);
    rightLine.position.set(1.6, 0.02, 0);
    rightLine.rotation.x = -Math.PI / 2;
    scene.add(rightLine);

    // --- Finish line (checkered strip) ---
    const finishGroup = new THREE.Group();
    const finishMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
    const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const base = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.05, 0.6), finishMat);
    base.position.y = 0.03;
    base.position.z = 8; // finish line at z=8
    finishGroup.add(base);

    // Checkered squares
    for (let i = -2; i < 2; i++) {
      for (let j = 0; j < 3; j++) {
        const square = new THREE.Mesh(
          new THREE.BoxGeometry(0.4, 0.06, 0.4),
          (i + j) % 2 === 0 ? whiteMat : finishMat
        );
        square.position.set(i * 0.4 + 0.2, 0.08, 8 + (j - 1) * 0.4);
        finishGroup.add(square);
      }
    }
    scene.add(finishGroup);

    // --- Start line (white strip) ---
    const startMat = new THREE.MeshStandardMaterial({ color: 0xeeeeee });
    const startLine = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.05, 0.3), startMat);
    startLine.position.y = 0.03;
    startLine.position.z = -6;
    scene.add(startLine);

    // --- Cars (red and blue) ---
    // Car body + details, each car is a group

    function createCar(color, isRed) {
      const car = new THREE.Group();

      // Body
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.4, metalness: 0.3 });
      const body = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.6, 2.8), bodyMat);
      body.position.y = 0.35;
      body.castShadow = true;
      car.add(body);

      // Cabin
      const cabinMat = new THREE.MeshStandardMaterial({ color: isRed ? 0x330000 : 0x000033, roughness: 0.6 });
      const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.5, 1.4), cabinMat);
      cabin.position.set(0, 0.75, -0.2);
      cabin.castShadow = true;
      car.add(cabin);

      // Wheels (4)
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
      const wheelPositions = [
        [-0.8, 0.25, 0.9],
        [0.8, 0.25, 0.9],
        [-0.8, 0.25, -0.9],
        [0.8, 0.25, -0.9]
      ];
      wheelPositions.forEach(pos => {
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.25, 16), wheelMat);
        wheel.rotation.x = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        car.add(wheel);
      });

      // Headlights (small spheres)
      const lightMat = new THREE.MeshStandardMaterial({ color: 0xffdd88, emissive: 0x553300 });
      const headL = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), lightMat);
      headL.position.set(-0.5, 0.35, 1.4);
      car.add(headL);
      const headR = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), lightMat);
      headR.position.set(0.5, 0.35, 1.4);
      car.add(headR);

      // Tail lights
      const tailMat = new THREE.MeshStandardMaterial({ color: 0xff3333, emissive: 0x330000 });
      const tailL = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 8), tailMat);
      tailL.position.set(-0.5, 0.35, -1.4);
      car.add(tailL);
      const tailR = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 8), tailMat);
      tailR.position.set(0.5, 0.35, -1.4);
      car.add(tailR);

      return car;
    }

    const redCar = createCar(0xff0000, true);
    const blueCar = createCar(0x0044ff, false);

    // Position cars at start
    redCar.position.set(-0.8, 0, -6); // red on left lane
    blueCar.position.set(0.8, 0, -6); // blue on right lane

    scene.add(redCar);
    scene.add(blueCar);

    // --- Animation variables ---
    const raceLength = 14; // from z=-6 to z=8
    const finishZ = 8;

    // Race state
    let blueZ = -6;
    let redZ = -6;
    let raceTime = 0;
    const totalRaceTime = 4.0; // seconds for full loop

    // Define speed curves
    // Blue: fast start, slows later
    // Red: slow start, accelerates mid, overtakes
    function blueSpeed(t) {
      // t: 0..1 progress, returns velocity factor
      // Blue leads early, then drops
      if (t < 0.3) return 1.6;
      if (t < 0.7) return 1.1;
      return 0.8;
    }

    function redSpeed(t) {
      // Red slow start, accelerates mid, wins
      if (t < 0.25) return 0.6;
      if (t < 0.6) return 1.4;
      return 1.8;
    }

    // We'll integrate speed to get positions
    let progress = 0; // 0..1

    // --- Status update ---
    const statusDiv = document.getElementById('status');

    // --- Animation loop ---
    const clock = new THREE.Clock();

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      raceTime += delta;

      // progress from 0 to 1 over totalRaceTime
      progress = (raceTime / totalRaceTime) % 1;

      // Integrate positions using speed functions
      // We'll approximate by using current progress to compute velocities
      // Use small steps for accuracy
      const steps = 20;
      const dt = delta / steps;
      for (let i = 0; i < steps; i++) {
        const t = (raceTime / totalRaceTime) % 1; // current progress
        const blueV = blueSpeed(t) * (raceLength / totalRaceTime);
        const redV = redSpeed(t) * (raceLength / totalRaceTime);
        blueZ += blueV * dt;
        redZ += redV * dt;

        // Clamp to race bounds
        if (blueZ < -6) blueZ = -6;
        if (redZ < -6) redZ = -6;
        if (blueZ > finishZ) blueZ = finishZ;
        if (redZ > finishZ) redZ = finishZ;
      }

      // Reset if both crossed finish line (red crosses first, then loop)
      if (redZ >= finishZ && blueZ >= finishZ) {
        // reset race
        raceTime = 0;
        redZ = -6;
        blueZ = -6;
        progress = 0;
        statusDiv.textContent = '🏁 RESET';
        setTimeout(() => { statusDiv.textContent = 'BLUE leads'; }, 500);
      } else if (redZ >= finishZ) {
        statusDiv.textContent = '🏁 RED WINS!';
      } else if (redZ > blueZ) {
        statusDiv.textContent = '🔴 RED overtakes!';
      } else {
        statusDiv.textContent = '🔵 BLUE leads';
      }

      // Update car positions
      redCar.position.z = redZ;
      blueCar.position.z = blueZ;

      // Slight bounce for wheels (visual)
      const bounce = Math.sin(raceTime * 10) * 0.02;
      redCar.position.y = bounce;
      blueCar.position.y = -bounce * 0.5;

      // Camera follows mid-point between cars, keep both in view
      const midZ = (redZ + blueZ) / 2;
      camera.position.z = midZ + 4.5;
      camera.position.x = 0;
      camera.position.y = 4.2;
      camera.lookAt(0, 0.8, midZ + 1);

      // Render
      renderer.render(scene, camera);

      requestAnimationFrame(animate);
    }

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start animation
    animate();

    // --- Add some clouds (simple boxes) ---
    const cloudMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x334455, transparent: true, opacity: 0.6 });
    for (let i = 0; i < 8; i++) {
      const cloud = new THREE.Mesh(new THREE.BoxGeometry(2 + Math.random() * 2, 0.6, 1.2), cloudMat);
      cloud.position.set((Math.random() - 0.5) * 12, 3 + Math.random() * 2, (Math.random() - 0.5) * 10);
      scene.add(cloud);
    }

    // --- Trees or simple roadside posts ---
    const postMat = new THREE.MeshStandardMaterial({ color: 0x8a5a2a });
    for (let i = -5; i <= 10; i += 2) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.8, 0.2), postMat);
      post.position.set(-2.2, 0.4, i);
      scene.add(post);
      const post2 = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.8, 0.2), postMat);
      post2.position.set(2.2, 0.4, i);
      scene.add(post2);
    }

    // Add distant mountains (simple triangles)
    const mountMat = new THREE.MeshStandardMaterial({ color: 0x6b705c, roughness: 1 });
    const mount1 = new THREE.Mesh(new THREE.ConeGeometry(3, 2, 8), mountMat);
    mount1.position.set(-8, 1, -4);
    mount1.rotation.z = 0.2;
    scene.add(mount1);
    const mount2 = new THREE.Mesh(new THREE.ConeGeometry(3.5, 2.5, 8), mountMat);
    mount2.position.set(7, 1.2, -6);
    mount2.rotation.z = -0.1;
    scene.add(mount2);
  </script>
</body>
</html>
```
